sys_ux_macroponent.props:
[
    {
        "defaultValue": "Selected Quote Option",
        "description": "The bold heading text, e.g. \"Selected Quote Option\".",
        "fieldType": "string",
        "label": "Title",
        "name": "title",
        "valueType": "string"
    },
    {
        "defaultValue": "The current selected quote option is below",
        "description": "Optional muted line beneath the title, e.g. \"The current selected quote option is below\".",
        "fieldType": "string",
        "label": "Description",
        "name": "description",
        "valueType": "string"
    },
    {
        "defaultValue": "",
        "description": "Optional muted inline note beside the title, e.g. \"Last refreshed 1m ago\". Plain gray text, no background. Leave blank to hide.",
        "fieldType": "string",
        "label": "Subtitle text",
        "name": "subtitle",
        "valueType": "string"
    },
    {
        "defaultValue": "",
        "description": "Optional status label after the title, e.g. \"Broker Approved\" — a Horizon now-highlighted-value. Leave blank to hide.",
        "fieldType": "string",
        "label": "Status text",
        "name": "status",
        "valueType": "string"
    },
    {
        "defaultValue": "green",
        "description": "Colour of the status label, from the theme: green → positive (approved), amber → warning (pending), red → critical (rejected), gray → neutral.",
        "fieldType": "choice",
        "label": "Status color",
        "name": "statusColor",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Green (approved)",
                    "value": "green"
                },
                {
                    "label": "Amber (pending)",
                    "value": "amber"
                },
                {
                    "label": "Red (rejected)",
                    "value": "red"
                },
                {
                    "label": "Gray (neutral)",
                    "value": "gray"
                }
            ],
            "schema": {
                "enum": [
                    "green",
                    "amber",
                    "red",
                    "gray"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "2",
        "description": "HTML heading element level (h1–h6). Controls document outline; style is set by Heading variant.",
        "fieldType": "choice",
        "label": "Heading level",
        "name": "headingLevel",
        "typeMetadata": {
            "choices": [
                {
                    "label": "h1",
                    "value": "1"
                },
                {
                    "label": "h2",
                    "value": "2"
                },
                {
                    "label": "h3",
                    "value": "3"
                },
                {
                    "label": "h4",
                    "value": "4"
                },
                {
                    "label": "h5",
                    "value": "5"
                },
                {
                    "label": "h6",
                    "value": "6"
                }
            ],
            "schema": {
                "enum": [
                    "1",
                    "2",
                    "3",
                    "4",
                    "5",
                    "6"
                ],
                "type": "string"
            }
        },
        "valueType": "string"
    },
    {
        "defaultValue": "header-secondary",
        "description": "Visual style of the title. \"header-secondary\" matches the default page-section look.",
        "fieldType": "choice",
        "label": "Heading variant",
        "name": "headingVariant",
        "typeMetadata": {
            "choices": [
                {
                    "label": "Header hero",
                    "value": "header-hero"
                },
                {
                    "label": "Header primary",
                    "value": "header-primary"
                },
                {
                    "label": "Header secondary",
                    "value": "header-secondary"
                },
                {
